```cpp
#include <Eigen/Dense>
#include <iostream>
#include <iomanip>
#include <cmath>

using namespace Eigen;

int main() {
    // Node coordinates
    // N1=(0,0,0), N2=(1,0,0), N3=(0,1,0), N4=(0,0,1)
    double x[4] = {0.0, 1.0, 0.0, 0.0};
    double y[4] = {0.0, 0.0, 1.0, 0.0};
    double z[4] = {0.0, 0.0, 0.0, 1.0};

    double E  = 200e9;
    double nu = 0.3;
    double GG = E / (2.0 * (1.0 + nu));

    // Build H (4x4): rows [1, x, y, z]
    Matrix4d H;
    for (int i = 0; i < 4; ++i) {
        H(i, 0) = 1.0;
        H(i, 1) = x[i];
        H(i, 2) = y[i];
        H(i, 3) = z[i];
    }

    // Invert H
    double hdeter = H.determinant();
    Matrix4d Hinv = H.inverse();
    hdeter = std::abs(hdeter);

    // G material matrix (6x6)
    Matrix<double,6,6> G = Matrix<double,6,6>::Zero();
    double temp1 = (1.0 + nu) * (1.0 - 2.0 * nu);
    double c1 = E * (1.0 - nu) / temp1;
    double c2 = E * nu / temp1;

    // Fortran G is stored column-major in a 6x6 (indices 1..36)
    // G(1)=c1, G(8)=c1, G(15)=c1  -> diagonal (1,1),(2,2),(3,3)
    // G(2)=c2, G(3)=c2, G(7)=c2, G(9)=c2, G(13)=c2, G(14)=c2
    // G(22)=GG, G(29)=GG, G(36)=GG -> (4,4),(5,5),(6,6)
    G(0,0) = c1; G(1,1) = c1; G(2,2) = c1;
    G(0,1) = c2; G(0,2) = c2;
    G(1,0) = c2; G(1,2) = c2;
    G(2,0) = c2; G(2,1) = c2;
    G(3,3) = GG; G(4,4) = GG; G(5,5) = GG;

    // Build C matrices (6x3) per node.
    // Fortran: J = 18*I - 18 (0-based offset into C array of 72)
    // C(J+1)=H(I+4), C(J+5)=H(I+8), C(J+9)=H(I+12),
    // C(J+11)=H(I+12), C(J+12)=H(I+8), C(J+13)=H(I+12),
    // C(J+15)=H(I+4), C(J+16)=H(I+8), C(J+17)=H(I+4)
    //
    // H is stored column-major: H(1..4)=col1, H(5..8)=col2, H(9..12)=col3, H(13..16)=col4
    // H(I+4)  = Hinv(I, 1)  (0-based col 1) -> d/dx of shape function i
    // H(I+8)  = Hinv(I, 2)  -> d/dy
    // H(I+12) = Hinv(I, 3)  -> d/dz
    //
    // C is 6x3 stored column-major: C(J+1..J+6)=col1, C(J+7..J+12)=col2, C(J+13..J+18)=col3
    // C(J+1)  = col1 row1 = dN/dx
    // C(J+5)  = col1 row5 = dN/dz
    // C(J+9)  = col2 row3 = dN/dy
    // C(J+11) = col2 row5 = dN/dz
    // C(J+12) = col2 row6 = dN/dy
    // C(J+13) = col3 row1 = dN/dx
    // C(J+15) = col3 row3 = dN/dy
    // C(J+16) = col3 row4 = dN/dz
    // C(J+17) = col3 row5 = dN/dx

    Matrix<double,6,3> C[4];
    for (int i = 0; i < 4; ++i) {
        C[i].setZero();
        double dNdx = Hinv(i, 1);
        double dNdy = Hinv(i, 2);
        double dNdz = Hinv(i, 3);

        // col1 (index 0)
        C[i](0, 0) = dNdx;   // row1
        C[i](4, 0) = dNdz;   // row5
        // col2 (index 1)
        C[i](2, 1) = dNdy;   // row3
        C[i](4, 1) = dNdz;   // row5
        C[i](5, 1) = dNdy;   // row6
        // col3 (index 2)
        C[i](0, 2) = dNdx;   // row1
        C[i](2, 2) = dNdy;   // row3
        C[i](3, 2) = dNdz;   // row4
        C[i](4, 2) = dNdx;   // row5
    }

    // HDETER = |det|/6
    double hdet = hdeter / 6.0;

    // Assemble 12x12 stiffness matrix
    Matrix<double,12,12> K = Matrix<double,12,12>::Zero();

    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 4; ++j) {
            // KIJ = C_i^T * G * C_j * hdet  (3x3)
            Matrix3d KIJ = C[i].transpose() * G * C[j] * hdet;
            K.block<3,3>(3*i, 3*j) = KIJ;
        }
    }

    // Output as JSON
    std::cout << std::setprecision(10);
    std::cout << "{\"stiffness_matrix\":[";
    for (int r = 0; r < 12; ++r) {
        std::cout << "[";
        for (int c = 0; c < 12; ++c) {
            std::cout << std::scientific << K(r, c);
            if (c < 11) std::cout << ",";
        }
        std::cout << "]";
        if (r < 11) std::cout << ",";
    }
    std::cout << "]}" << std::endl;

    return 0;
}
